        ProcessLevellingUpFX();
    switch (Timer.CurrentState) {
    case 2:
        UpdateButtonHeld();
        break;
    case 3:
        if (SpellFinished && ReleaseDelayFrameCount <= 0)
            parent->RemoveTC(0x9d);
        break;
    }
}

